   226  static int
   227  secondline_is_bases(const unsigned char *u, const unsigned char *ulim)
   228  {
   229      // Skip to second line, returning false if there isn't one
   230      u = memchr(u, '\n', ulim - u);
   231      if (u == NULL || ++u == ulim) return 0;
   232
   233      // Scan over all base-encoding letters (including 'N' but not SEQ's '=')
   234      while (u < ulim && (seq_nt16_table[*u] != 15 || toupper(*u) == 'N')) {
   235          if (*u == '=') return 0;
   236          u++;
   237      }
   238
   239      return (u == ulim || *u == '\r' || *u == '\n')? 1 : 0;
   240  }
