   301  // Match COLUMNS as a prefix against PATTERN (so COLUMNS may run out first).
   302  // Returns len(COLUMNS) (modulo '+'), or 0 if there is a mismatched entry.
   303  static int colmatch(const char *columns, const char *pattern)
   304  {
   305      int i;
   306      for (i = 0; columns[i] != '\0'; i++) {
   307          if (pattern[i] == '+') return i;
   308          if (! (columns[i] == pattern[i] || pattern[i] == 'Z')) return 0;
   309      }
   310
   311      return i;
   312  }
